\noindent\emph{(Prosegue la dimostrazione del Teorema~1: il valore $j=h(I(z))$ è noto e
resta da determinare $\bar x$ in tempo costante; per $\bar y$ si procede in modo simmetrico.)}

\begin{itemize}
  \item Se $h(I(x))=j$, allora $x$ sta già sul run di $z$, cioè $x=\bar x$: ho finito.
  \item Altrimenti, sia $w$ l'ultimo nodo del cammino $x\rightsquigarrow\bar x$ che viene
        mappato in un nodo di altezza $<j$ (tutti i nodi del cammino che stanno
        strettamente sotto $\bar x$ hanno infatti $h(I(\cdot))<j$).
\end{itemize}

\begin{osservazione}
  $w$ è figlio di $\bar x$ ed è il \emph{leader} del proprio run.
  Dunque, se determino $w$ ho finito, perché $\bar x=\mathrm{parent}(w)$.
\end{osservazione}

\begin{figure}[H]
  \centering
  \input{tikz/lca-xbar-w.tikz}
  \caption{Il caso $h(I(x))\neq j$: $\bar x$ appartiene al run di $z$, mentre $w$ è il
  figlio di $\bar x$ sul cammino che scende verso $x$ ed è il leader del proprio run.}
\end{figure}

Il nodo $w$ si determina con quattro osservazioni, ciascuna eseguibile in $\Oh(1)$:
\begin{itemize}
  \item $h(I(w))$ è la posizione del primo $1$ di $A_x$ a destra di $j$, cioè la più
        grande posizione $<j$ in cui $A_x$ vale $1$;
  \item $I(w)$ coincide con $I(x)$ in tutti i bit a sinistra della posizione $h(I(w))$;
        quindi
        \[
          I(w)\;=\;\bigl(\text{bit di } I(x) \text{ a sinistra di } h(I(w))\bigr)
          \;\Vert\;1\;\Vert\;0\cdots0 ;
        \]
  \item $w$ è il leader del run individuato da $I(w)$, cioè $w=L(I(w))$;
  \item $\bar x$ è il padre di $w$.
\end{itemize}

\begin{osservazione}
  Se $h(I(x))=j$, allora dentro $\T(x)$ i bit a sinistra della posizione $j$ restano
  fissi e possono cambiare solo quelli dalla posizione $j$ in giù: per il Lemma, ogni
  $u\in\T(x)$ ha $I(u)\in\B(I(x))$, cioè $I(u)$ e $I(x)$ hanno gli stessi bit a
  sinistra di $j$. È esattamente questo che permette di ricostruire $I(w)$ a partire
  da $I(x)$.
\end{osservazione}

\subsection{Algoritmo per \texorpdfstring{$\lca(x,y)$}{lca(x,y)} in tempo \texorpdfstring{$\Oh(1)$}{O(1)}}

\begin{osservazione}
  Tutte le informazioni che l'algoritmo usa devono essere state rese disponibili in
  fase di pre-processing.
\end{osservazione}

\begin{algorithm}[H]
\caption{Query $\lca(x,y)$ in tempo costante (passi 1--3; i passi 4--5 proseguono a p.~40)}
\begin{algorithmic}
  \State \textbf{1)} determino $b=\lca_{\B}\bigl(I(x),I(y)\bigr)$;
  \State \textbf{2)} determino il minimo $j\ge h(b)$ con $A_x[j]=A_y[j]=1$;
         \Comment{per il Teorema~2, $j=h(I(z))$}
  \State \textbf{3)} determino $\bar x$, il nodo del run di $z$ più vicino a $x$, così:
  \State \quad \textbf{3a)} trovo la posizione $\ell$ minima con $A_x[\ell]=1$;
         \Comment{$\ell=h(I(x))$}
  \State \quad \textbf{3b)} se $\ell=j$, allora $\bar x=x$: ho finito;
  \State \quad \textbf{3c)} se $\ell<j$, trovo la posizione massima $k<j$ con $A_x[k]=1$;
  \State \qquad prendo $I(x)$, azzero i bit a destra della posizione $k$ e vi metto un
         $1$ in posizione $k$: il numero ottenuto è $I(w)$;
  \State \qquad leggo $w=L(I(w))$ e pongo
         $\bar x=\mathrm{parent}(w)=\mathrm{parent}\bigl(L(I(w))\bigr)$.
\end{algorithmic}
\end{algorithm}
